// ---- extended checks ----
{
  const assert = require('node:assert/strict');
  const snapshot = (repo) => JSON.stringify({ documents: repo.documents, audit: repo.audit });
  const docs = [
    { id: 'a-own', tenant: 'a', owner: 'u',   deleted: false, archived: false },
    { id: 'a-other', tenant: 'a', owner: 'u2', deleted: false, archived: false },
    { id: 'a-deleted', tenant: 'a', owner: 'u', deleted: true,  archived: false },
    { id: 'b-doc', tenant: 'b', owner: 'u',   deleted: false, archived: false },
    { id: 'a-archived', tenant: 'a', owner: 'u2', deleted: false, archived: true },
    { id: 'b-archived', tenant: 'b', owner: 'u',   deleted: false, archived: true },
  ];
  const makeRepo = () => new DocumentRepository(docs.map(d => ({ ...d })));
  const expectFailure = (repo, actor, id, message) => {
    const before = snapshot(repo);
    assert.throws(() => new DocumentService(repo).archive(actor, id), new RegExp(message));
    assert.equal(snapshot(repo), before, `state changed on failed archive of ${id}`);
  };

  // invisible documents: missing, deleted, foreign tenant -> not found, even for admin
  {
    const repo = makeRepo();
    for (const actor of [
      { tenant: 'a', user: 'u', role: 'admin' },
      { tenant: 'a', user: 'u', role: 'editor' },
      { tenant: 'a', user: 'u', role: 'viewer' },
    ]) {
      expectFailure(repo, actor, 'missing', 'not found');
      expectFailure(repo, actor, 'a-deleted', 'not found');
      expectFailure(repo, actor, 'b-doc', 'not found');
      expectFailure(repo, actor, 'b-archived', 'not found');
    }
  }

  // visibility precedes permission: foreign-tenant + would-be-forbidden yields not found
  {
    const repo = makeRepo();
    expectFailure(repo, { tenant: 'a', user: 'u', role: 'editor' }, 'b-doc', 'not found');
    expectFailure(repo, { tenant: 'a', user: 'u', role: 'viewer' }, 'b-doc', 'not found');
  }

  // editor may archive own; audit appended exactly
  {
    const repo = makeRepo();
    const service = new DocumentService(repo);
    service.archive({ tenant: 'a', user: 'u', role: 'editor' }, 'a-own');
    assert.equal(repo.find('a-own').archived, true);
    assert.deepEqual(repo.audit, [{ actor: 'u', document: 'a-own' }]);
  }

  // editor may not archive another's document
  {
    const repo = makeRepo();
    expectFailure(repo, { tenant: 'a', user: 'u', role: 'editor' }, 'a-other', 'forbidden');
  }

  // viewer never may, even for their own document
  {
    const repo = makeRepo();
    expectFailure(repo, { tenant: 'a', user: 'u', role: 'viewer' }, 'a-own', 'forbidden');
  }

  // repeating archive is a no-op but permission is still enforced first
  {
    const repo = makeRepo();
    const service = new DocumentService(repo);
    service.archive({ tenant: 'a', user: 'u', role: 'editor' }, 'a-own');
    service.archive({ tenant: 'a', user: 'u', role: 'editor' }, 'a-own');
    assert.deepEqual(repo.audit, [{ actor: 'u', document: 'a-own' }]);
    expectFailure(repo, { tenant: 'a', user: 'u', role: 'editor' }, 'a-archived', 'forbidden');
    expectFailure(repo, { tenant: 'a', user: 'u', role: 'viewer' }, 'a-archived', 'forbidden');
  }

  // admin may archive archived visible document as a no-op without new audit
  {
    const repo = makeRepo();
    const admin = { tenant: 'a', user: 'u', role: 'admin' };
    new DocumentService(repo).archive(admin, 'a-archived');
    assert.deepEqual(repo.audit, []);
    assert.equal(repo.find('a-archived').archived, true);
  }

  console.log('extended checks passed');
}
EOF
npx tsc -p tsconfig.json && node checks/public.cjs && echo 'ALL CHECKS PASSED'

